import { X } from 'lucide-react'
import { Popover as PopoverPrimitive } from 'radix-ui'
import type { ComponentProps } from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../../button'

export const fieldShellClassName =
  'flex h-9 w-full min-w-0 items-center rounded-md border border-input bg-transparent px-3 text-base shadow-xs transition-[color,box-shadow] outline-none focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50 has-aria-invalid:border-destructive has-aria-invalid:ring-destructive/20 md:text-sm dark:bg-input/30 dark:has-aria-invalid:ring-destructive/40'

export const fieldTriggerClassName =
  'flex h-9 w-full min-w-0 items-center justify-between gap-2 rounded-md border border-input bg-transparent px-3 py-2 text-sm whitespace-nowrap shadow-xs transition-[color,box-shadow] outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:bg-input/30 dark:hover:bg-input/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*=size-])]:size-4 [&_svg:not([class*=text-])]:text-muted-foreground'

export function FieldClearButton({
  label = 'Clear value',
  className,
  onClear,
}: {
  label?: string
  className?: string
  onClear: () => void
}) {
  return (
    <ProButton
      variant="ghost"
      size="icon-sm"
      tabIndex={-1}
      aria-label={label}
      onMouseDown={(event) => {
        event.preventDefault()
        event.stopPropagation()
      }}
      onClick={(event) => {
        event.stopPropagation()
        onClear()
      }}
      className={cn('ml-1.5', className)}
    >
      <X />
    </ProButton>
  )
}

export function FieldClearAction({
  label = 'Clear value',
  className,
  onClear,
}: {
  label?: string
  className?: string
  onClear: () => void
}) {
  function clear(event: { preventDefault: () => void; stopPropagation: () => void }) {
    event.preventDefault()
    event.stopPropagation()
    onClear()
  }

  return (
    // biome-ignore lint/a11y/useSemanticElements: field triggers are buttons, so the clear affordance cannot be a nested button.
    <span
      role="button"
      tabIndex={0}
      aria-label={label}
      className={cn(
        "inline-flex size-4 items-center justify-center rounded-sm outline-hidden [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      onPointerDown={clear}
      onClick={clear}
      onKeyDown={(event) => {
        if (event.key !== 'Enter' && event.key !== ' ') return
        clear(event)
      }}
    >
      <X />
    </span>
  )
}

export function FieldPopoverContent({
  className,
  align = 'center',
  sideOffset = 4,
  ...props
}: ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        data-slot="field-popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          'z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95',
          className,
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  )
}

'use client'

import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from 'lucide-react'
import { useEffect, useRef } from 'react'
import {
  type DayButtonProps,
  DayPicker,
  type DayPickerProps,
  getDefaultClassNames,
} from 'react-day-picker'
import { cn } from '@/lib/utils'
import { buttonVariants } from '../../button'

export function FieldCalendar({
  className,
  showOutsideDays = true,
  ...props
}: Omit<
  DayPickerProps,
  'captionLayout' | 'classNames' | 'components' | 'formatters' | 'showWeekNumber'
>) {
  const defaultClassNames = getDefaultClassNames()

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        'group/calendar bg-background p-3 [--cell-size:--spacing(8)] [[data-slot=card-content]_&]:bg-transparent [[data-slot=field-popover-content]_&]:bg-transparent',
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className,
      )}
      captionLayout="label"
      formatters={{
        formatMonthDropdown: (date) => date.toLocaleString('default', { month: 'short' }),
      }}
      classNames={{
        root: cn('w-fit', defaultClassNames.root),
        months: cn('relative flex flex-col gap-4 md:flex-row', defaultClassNames.months),
        month: cn('flex w-full flex-col gap-4', defaultClassNames.month),
        nav: cn(
          'absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1',
          defaultClassNames.nav,
        ),
        button_previous: cn(
          buttonVariants({ variant: 'ghost' }),
          'size-(--cell-size) p-0 select-none aria-disabled:opacity-50',
          defaultClassNames.button_previous,
        ),
        button_next: cn(
          buttonVariants({ variant: 'ghost' }),
          'size-(--cell-size) p-0 select-none aria-disabled:opacity-50',
          defaultClassNames.button_next,
        ),
        month_caption: cn(
          'flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)',
          defaultClassNames.month_caption,
        ),
        dropdowns: cn(
          'flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium',
          defaultClassNames.dropdowns,
        ),
        dropdown_root: cn(
          'relative rounded-md border border-input shadow-xs has-focus:border-ring has-focus:ring-[3px] has-focus:ring-ring/50',
          defaultClassNames.dropdown_root,
        ),
        dropdown: cn('absolute inset-0 bg-popover opacity-0', defaultClassNames.dropdown),
        caption_label: cn('font-medium select-none', 'text-sm', defaultClassNames.caption_label),
        weekdays: cn('flex', defaultClassNames.weekdays),
        weekday: cn(
          'flex-1 rounded-md text-[0.8rem] font-normal text-muted-foreground select-none',
          defaultClassNames.weekday,
        ),
        week: cn('mt-2 flex w-full', defaultClassNames.week),
        day: cn(
          'group/day relative aspect-square size-full p-0 text-center select-none [&:last-child[data-selected=true]_button]:rounded-r-md',
          '[&:first-child[data-selected=true]_button]:rounded-l-md',
          defaultClassNames.day,
        ),
        range_start: cn('rounded-l-md bg-accent', defaultClassNames.range_start),
        range_middle: cn('rounded-none', defaultClassNames.range_middle),
        range_end: cn('rounded-r-md bg-accent', defaultClassNames.range_end),
        today: cn(
          'rounded-md bg-accent text-accent-foreground data-[selected=true]:rounded-none',
          defaultClassNames.today,
        ),
        outside: cn(
          'text-muted-foreground aria-selected:text-muted-foreground',
          defaultClassNames.outside,
        ),
        disabled: cn('text-muted-foreground opacity-50', defaultClassNames.disabled),
        hidden: cn('invisible', defaultClassNames.hidden),
      }}
      components={{
        Root: ({ className, rootRef, ...rootProps }) => (
          <div data-slot="field-calendar" ref={rootRef} className={className} {...rootProps} />
        ),
        Chevron: ({ className, orientation, ...chevronProps }) => {
          if (orientation === 'left') {
            return <ChevronLeftIcon className={cn('size-4', className)} {...chevronProps} />
          }

          if (orientation === 'right') {
            return <ChevronRightIcon className={cn('size-4', className)} {...chevronProps} />
          }

          return <ChevronDownIcon className={cn('size-4', className)} {...chevronProps} />
        },
        DayButton: FieldCalendarDayButton,
      }}
      {...props}
    />
  )
}

function FieldCalendarDayButton({ className, day, modifiers, ...props }: DayButtonProps) {
  const defaultClassNames = getDefaultClassNames()
  const ref = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <button
      ref={ref}
      type="button"
      data-day={day.date.toLocaleDateString()}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        buttonVariants({ variant: 'ghost', size: 'icon' }),
        'flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 leading-none font-normal group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-ring group-data-[focused=true]/day:ring-[3px] group-data-[focused=true]/day:ring-ring/50 data-[range-end=true]:rounded-md data-[range-end=true]:rounded-r-md data-[range-end=true]:bg-primary data-[range-end=true]:text-primary-foreground data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground data-[range-start=true]:rounded-md data-[range-start=true]:rounded-l-md data-[range-start=true]:bg-primary data-[range-start=true]:text-primary-foreground data-[selected-single=true]:bg-primary data-[selected-single=true]:text-primary-foreground dark:hover:text-accent-foreground [&>span]:text-xs [&>span]:opacity-70',
        defaultClassNames.day,
        className,
      )}
      {...props}
    />
  )
}

'use client'

import { Eye, EyeOff } from 'lucide-react'
import { Slider as SliderPrimitive } from 'radix-ui'
import {
  type ChangeEvent,
  type ChangeEventHandler,
  type ComponentProps,
  type ReactNode,
  type Ref,
  useEffect,
  useRef,
  useState,
} from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../../button'
import { FieldClearButton, fieldShellClassName } from '../shared/field'

interface InputProps
  extends Omit<
    ComponentProps<'input'>,
    'children' | 'className' | 'defaultValue' | 'onChange' | 'prefix' | 'ref' | 'value'
  > {
  value?: string | number | readonly string[]
  defaultValue?: string | number | readonly string[]
  onChange?: ChangeEventHandler<HTMLInputElement>
  className?: string
  inputClassName?: string
  prefix?: ReactNode
  suffix?: ReactNode
  allowClear?: boolean
  onClear?: () => void
  ref?: Ref<HTMLInputElement>
}

export function Input({
  prefix,
  suffix,
  allowClear = true,
  onClear,
  className,
  inputClassName,
  type,
  value,
  defaultValue,
  onChange,
  disabled,
  readOnly,
  ref,
  ...props
}: InputProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  function setInputRef(node: HTMLInputElement | null) {
    inputRef.current = node
    if (typeof ref === 'function') {
      ref(node)
      return
    }
    if (ref) ref.current = node
  }

  const [internalValue, setInternalValue] = useState(defaultValue ?? '')
  const currentValue = value ?? internalValue
  const showClear =
    !!allowClear && currentValue !== '' && currentValue != null && !disabled && !readOnly
  const hasPrefix = prefix != null && prefix !== false
  const hasSuffix = (suffix != null && suffix !== false) || showClear

  function emitValue(nextValue: string, event?: ChangeEvent<HTMLInputElement>) {
    if (value === undefined) setInternalValue(nextValue)
    const inputEl = inputRef.current
    if (!inputEl) return

    inputEl.value = nextValue
    onChange?.({
      ...event,
      target: inputEl,
      currentTarget: inputEl,
    } as ChangeEvent<HTMLInputElement>)
  }

  return (
    <div
      className={cn(
        fieldShellClassName,
        hasPrefix && 'pl-0',
        hasSuffix && 'pr-0',
        disabled && 'pointer-events-none opacity-50',
        className,
      )}
    >
      {hasPrefix && <div className="flex shrink-0 items-center">{prefix}</div>}

      <input
        ref={setInputRef}
        type={type}
        data-slot="input"
        value={String(currentValue ?? '')}
        onChange={(event) => emitValue(event.target.value, event)}
        disabled={disabled}
        readOnly={readOnly}
        className={cn(
          'h-auto min-w-0 flex-1 rounded-none border-0 bg-transparent p-0 text-base shadow-none outline-none selection:bg-primary selection:text-primary-foreground file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:ring-0 disabled:pointer-events-none disabled:cursor-not-allowed md:text-sm dark:bg-transparent',
          inputClassName,
        )}
        {...props}
      />

      {hasSuffix && (
        <div className="flex shrink-0 items-center">
          {showClear && (
            <FieldClearButton
              label="Clear input"
              className="ml-0"
              onClear={() => {
                onClear?.()
                emitValue('')
              }}
            />
          )}
          {suffix}
        </div>
      )}
    </div>
  )
}

export function Password({
  className,
  suffix,
  inputClassName,
  ref,
  ...props
}: Omit<InputProps, 'type'>) {
  const [visible, setVisible] = useState(false)

  return (
    <Input
      ref={ref}
      {...props}
      type={visible ? 'text' : 'password'}
      className={className}
      inputClassName={inputClassName}
      suffix={
        <>
          {suffix}
          <ProButton
            variant="ghost"
            size="icon-sm"
            tabIndex={-1}
            onClick={() => setVisible((value) => !value)}
            aria-label={visible ? 'Hide password' : 'Show password'}
          >
            {visible ? <EyeOff /> : <Eye />}
          </ProButton>
        </>
      }
    />
  )
}

interface TextareaProps extends Omit<ComponentProps<'textarea'>, 'ref'> {
  onClear?: () => void
  ref?: Ref<HTMLTextAreaElement>
}

export function Textarea({
  onClear,
  className,
  value,
  defaultValue,
  onChange,
  disabled,
  readOnly,
  ref,
  ...props
}: TextareaProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  function setTextareaRef(node: HTMLTextAreaElement | null) {
    textareaRef.current = node
    if (typeof ref === 'function') {
      ref(node)
      return
    }
    if (ref) ref.current = node
  }
  const [internalValue, setInternalValue] = useState(defaultValue ?? '')
  const currentValue = value ?? internalValue
  const showClear = currentValue !== '' && currentValue != null && !disabled && !readOnly

  return (
    <div className="relative w-full">
      <textarea
        ref={setTextareaRef}
        data-slot="textarea"
        value={currentValue}
        onChange={(event) => {
          if (value === undefined) setInternalValue(event.target.value)
          onChange?.(event)
        }}
        disabled={disabled}
        readOnly={readOnly}
        className={cn(
          'flex field-sizing-content min-h-16 w-full rounded-md border border-input bg-transparent px-3 py-2 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 md:text-sm dark:bg-input/30 dark:aria-invalid:ring-destructive/40',
          showClear && 'pr-8',
          className,
        )}
        {...props}
      />
      {showClear && (
        <FieldClearButton
          label="Clear textarea"
          onClear={() => {
            if (value === undefined) setInternalValue('')
            onClear?.()

            const field = textareaRef.current
            if (!field) return

            field.value = ''
            onChange?.({
              target: field,
              currentTarget: field,
            } as ChangeEvent<HTMLTextAreaElement>)
          }}
          className="absolute top-2 right-2 z-10 ml-0"
        />
      )}
    </div>
  )
}

export function Digit({
  value,
  onChange,
  placeholder = 'Enter number',
  disabled,
  className,
  min,
  max,
  step = 1,
  ...props
}: Omit<InputProps, 'value' | 'defaultValue' | 'onChange' | 'allowClear'> & {
  value?: number
  onChange?: (value: number | undefined) => void
}) {
  return (
    <Input
      {...props}
      type="number"
      value={value != null && !Number.isNaN(value) ? value : ''}
      onChange={(event) => {
        if (event.target.value === '') {
          onChange?.(undefined)
          return
        }
        const nextValue = Number(event.target.value)
        if (Number.isNaN(nextValue)) {
          onChange?.(undefined)
          return
        }
        onChange?.(nextValue)
      }}
      placeholder={placeholder}
      disabled={disabled}
      min={min}
      max={max}
      step={step}
      className={className}
      onClear={() => onChange?.(undefined)}
    />
  )
}

export function DigitRange({
  value,
  onChange,
  placeholder = ['Min', 'Max'],
  disabled,
  className,
}: {
  value?: { min?: number; max?: number }
  onChange?: (value: { min?: number; max?: number } | undefined) => void
  placeholder?: [string, string]
  disabled?: boolean
  className?: string
}) {
  const minValue = value?.min
  const maxValue = value?.max
  const hasMinValue = minValue != null && !Number.isNaN(minValue)
  const hasMaxValue = maxValue != null && !Number.isNaN(maxValue)
  const showClear = (hasMinValue || hasMaxValue) && !disabled

  function updateRange(key: 'min' | 'max', inputValue: string) {
    const parsed = Number(inputValue)
    const nextNumber = inputValue !== '' && !Number.isNaN(parsed) ? parsed : undefined
    const nextValue = {
      ...value,
      [key]: nextNumber,
    }
    if (
      (nextValue.min != null && !Number.isNaN(nextValue.min)) ||
      (nextValue.max != null && !Number.isNaN(nextValue.max))
    ) {
      onChange?.(nextValue)
      return
    }
    onChange?.(undefined)
  }

  return (
    <div
      data-slot="digit-range"
      className={cn(
        fieldShellClassName,
        'overflow-hidden [&_input]:h-auto [&_input]:w-0 [&_input]:min-w-0 [&_input]:flex-1 [&_input]:rounded-none [&_input]:border-0 [&_input]:bg-transparent [&_input]:p-0 [&_input]:text-center [&_input]:text-base [&_input]:shadow-none [&_input]:outline-none [&_input]:selection:bg-primary [&_input]:selection:text-primary-foreground [&_input]:placeholder:text-muted-foreground [&_input]:focus-visible:ring-0 [&_input]:disabled:pointer-events-none [&_input]:disabled:cursor-not-allowed md:[&_input]:text-sm dark:[&_input]:bg-transparent',
        showClear && 'pr-0',
        disabled && 'pointer-events-none opacity-50',
        className,
      )}
    >
      <input
        aria-label="Minimum value"
        type="text"
        inputMode="decimal"
        value={hasMinValue ? minValue : ''}
        onChange={(event) => updateRange('min', event.target.value)}
        placeholder={placeholder[0]}
        disabled={disabled}
      />
      <span className="shrink-0 px-2 text-muted-foreground select-none">~</span>
      <input
        aria-label="Maximum value"
        type="text"
        inputMode="decimal"
        value={hasMaxValue ? maxValue : ''}
        onChange={(event) => updateRange('max', event.target.value)}
        placeholder={placeholder[1]}
        disabled={disabled}
      />
      {showClear && (
        <FieldClearButton
          label="Clear range"
          className="ml-0"
          onClear={() => onChange?.(undefined)}
        />
      )}
    </div>
  )
}

export function Slider({
  value,
  defaultValue,
  onChange,
  min = 0,
  max = 100,
  step = 1,
  disabled,
  className,
  ...props
}: Omit<
  ComponentProps<typeof SliderPrimitive.Root>,
  'value' | 'defaultValue' | 'onValueChange' | 'min' | 'max' | 'step' | 'disabled' | 'className'
> & {
  value?: number
  defaultValue?: number
  onChange?: (value: number) => void
  min?: number
  max?: number
  step?: number
  disabled?: boolean
  className?: string
}) {
  return (
    <SliderPrimitive.Root
      data-slot="slider"
      value={value === undefined ? undefined : [value]}
      defaultValue={value === undefined ? [defaultValue ?? min] : undefined}
      onValueChange={(nextValue) => onChange?.(nextValue[0] ?? min)}
      min={min}
      max={max}
      step={step}
      disabled={disabled}
      className={cn(
        'relative flex w-full touch-none items-center select-none data-[disabled]:opacity-50',
        className,
      )}
      {...props}
    >
      <SliderPrimitive.Track
        data-slot="slider-track"
        className="relative h-1.5 w-full grow overflow-hidden rounded-full bg-muted"
      >
        <SliderPrimitive.Range data-slot="slider-range" className="absolute h-full bg-primary" />
      </SliderPrimitive.Track>
      <SliderPrimitive.Thumb
        data-slot="slider-thumb"
        className={
          'block size-4 shrink-0 rounded-full border border-primary bg-primary shadow-sm ring-ring/50 transition-[color,box-shadow] hover:ring-4 focus-visible:ring-4 focus-visible:outline-hidden disabled:pointer-events-none disabled:opacity-50'
        }
      />
    </SliderPrimitive.Root>
  )
}

export function Money({
  value,
  onChange,
  placeholder = '0.00',
  disabled,
  className,
  prefix,
  suffix,
  ...props
}: Omit<InputProps, 'value' | 'defaultValue' | 'onChange'> & {
  value?: number
  onChange?: (value: number | undefined) => void
}) {
  return (
    <Input
      type="text"
      inputMode="decimal"
      value={value === undefined ? '' : String(value)}
      onChange={(event) => {
        const parsed = parseFloat(event.target.value.replace(/[^0-9.]/g, ''))
        if (Number.isNaN(parsed)) onChange?.(undefined)
        else onChange?.(parsed)
      }}
      placeholder={placeholder}
      disabled={disabled}
      prefix={<span className="px-3">{prefix ?? '$'}</span>}
      suffix={suffix ? <span className="px-3">{suffix}</span> : undefined}
      className={className}
      {...props}
    />
  )
}

export function Captcha({
  value,
  onChange,
  onSend,
  placeholder = 'Enter captcha',
  disabled,
  className,
  ...inputProps
}: Omit<InputProps, 'inputClassName' | 'suffix' | 'value' | 'onChange' | 'disabled'> & {
  value?: string
  onChange?: (event: ChangeEvent<HTMLInputElement>) => void
  onSend?: () => void | Promise<void>
  disabled?: boolean
}) {
  const deadlineRef = useRef(0)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const [remaining, setRemaining] = useState(0)

  function stopCountdown() {
    deadlineRef.current = 0
    if (timerRef.current) {
      clearInterval(timerRef.current)
      timerRef.current = null
    }
    setRemaining(0)
  }

  useEffect(() => () => stopCountdown(), [])

  return (
    <Input
      autoComplete="off"
      {...inputProps}
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      disabled={disabled}
      className={className}
      suffix={
        <ProButton
          variant="ghost"
          size="sm"
          disabled={disabled || remaining > 0}
          onClick={async (event) => {
            event.stopPropagation()
            await onSend?.()
            stopCountdown()
            deadlineRef.current = Date.now() + 60_000
            setRemaining(60_000)
            timerRef.current = setInterval(() => {
              const nextRemaining = Math.max(deadlineRef.current - Date.now(), 0)
              setRemaining(nextRemaining)
              if (nextRemaining === 0) stopCountdown()
            }, 250)
          }}
        >
          {remaining > 0 ? `${Math.ceil(remaining / 1000)}s` : 'Get code'}
        </ProButton>
      }
    />
  )
}

'use client'

import { Command as CommandPrimitive } from 'cmdk'
import { Check, ChevronDown, ChevronRight, ChevronUp, SearchIcon } from 'lucide-react'
import { Popover as PopoverPrimitive, Select as SelectPrimitive } from 'radix-ui'
import { type ReactNode, useEffect, useState } from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../../button'
import { CheckboxControl } from '../checkbox'
import { FieldClearAction, FieldPopoverContent, fieldTriggerClassName } from '../shared/field'

interface NestedOption {
  label: string
  value: string
  disabled?: boolean
  children?: NestedOption[]
}

const EMPTY_CASCADER_OPTIONS: NestedOption[] = []
const EMPTY_CASCADER_VALUE: string[] = []

export function Select({
  value,
  defaultValue,
  onChange,
  placeholder,
  disabled,
  required,
  options,
  allowClear = false,
  multiple = false,
  searchable = false,
  className,
}: {
  value?: string | string[]
  defaultValue?: string | string[]
  onChange?: (value: string | string[] | undefined) => void
  placeholder?: string
  disabled?: boolean
  required?: boolean
  options?: {
    label: ReactNode
    value: string
    description?: ReactNode
    disabled?: boolean
  }[]
  allowClear?: boolean
  multiple?: boolean
  searchable?: boolean
  className?: string
}) {
  const [internalValue, setInternalValue] = useState<string | string[] | undefined>(defaultValue)
  const [open, setOpen] = useState(false)
  const currentValue = value ?? internalValue
  const selectedValues = getSelectedValues(currentValue)
  const selectedValueSet = new Set(selectedValues)
  const selectedOptions = options?.filter((option) => selectedValueSet.has(option.value)) ?? []
  const selectedCount = selectedOptions.length
  const selectPlaceholder = placeholder ?? 'Select...'
  const showClear = allowClear && selectedValues.length > 0 && !disabled && !required

  function handleChange(nextValue: string | string[] | undefined) {
    if (value === undefined) setInternalValue(nextValue)
    onChange?.(nextValue)
  }

  function handleCommandSelect(optionValue: string) {
    if (!multiple) {
      handleChange(optionValue)
      setOpen(false)
      return
    }

    const nextValues = selectedValueSet.has(optionValue)
      ? selectedValues.filter((selectedValue) => selectedValue !== optionValue)
      : [...selectedValues, optionValue]
    if (nextValues.length === 0) {
      handleChange(undefined)
      return
    }
    handleChange(nextValues)
  }

  if (multiple || searchable) {
    return (
      <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
        <PopoverPrimitive.Trigger asChild>
          <button
            type="button"
            role="combobox"
            aria-expanded={open}
            disabled={disabled}
            className={cn(
              fieldTriggerClassName,
              'group/select w-full justify-between font-normal disabled:pointer-events-none disabled:opacity-50',
              selectedCount === 0 && 'text-muted-foreground hover:text-muted-foreground',
              className,
            )}
          >
            <span className="flex min-w-0 flex-1 items-center gap-1 truncate text-left">
              {renderSelectedOptions(selectedOptions, selectedCount, selectPlaceholder)}
            </span>
            <span className="relative flex size-4 shrink-0 items-center justify-center">
              {showClear && (
                <FieldClearAction
                  label="Clear selection"
                  onClear={() => handleChange(undefined)}
                  className={
                    'pointer-events-none absolute inset-0 z-10 opacity-0 group-hover/select:pointer-events-auto group-hover/select:opacity-100 group-focus-within/select:pointer-events-auto group-focus-within/select:opacity-100'
                  }
                />
              )}
              <ChevronDown
                className={cn(
                  'size-4 opacity-50',
                  showClear && 'group-hover/select:opacity-0 group-focus-within/select:opacity-0',
                )}
              />
            </span>
          </button>
        </PopoverPrimitive.Trigger>
        <FieldPopoverContent className="w-[var(--radix-popover-trigger-width)] p-0" align="start">
          <CommandPrimitive
            className={
              'flex size-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground'
            }
          >
            {searchable && (
              <div className="flex h-9 items-center gap-2 border-b px-3">
                <SearchIcon className="size-4 shrink-0 opacity-50" />
                <CommandPrimitive.Input
                  placeholder={placeholder ?? 'Search...'}
                  className={
                    'flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-hidden placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50'
                  }
                />
              </div>
            )}
            <CommandPrimitive.List className="max-h-[300px] scroll-py-1 overflow-x-hidden overflow-y-auto">
              <CommandPrimitive.Empty className="py-6 text-center text-sm">
                No results found.
              </CommandPrimitive.Empty>
              <CommandPrimitive.Group className="overflow-hidden p-1 text-foreground">
                {options?.map((option) => (
                  <CommandPrimitive.Item
                    key={option.value}
                    value={option.value}
                    disabled={option.disabled}
                    onSelect={() => handleCommandSelect(option.value)}
                    className={
                      "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground"
                    }
                  >
                    <Check
                      className={cn(
                        'size-4',
                        selectedValueSet.has(option.value) ? 'opacity-100' : 'opacity-0',
                      )}
                    />
                    <span className="grid gap-1">
                      <span>{option.label}</span>
                      {option.description != null && (
                        <span className="text-xs leading-snug text-muted-foreground">
                          {option.description}
                        </span>
                      )}
                    </span>
                  </CommandPrimitive.Item>
                ))}
              </CommandPrimitive.Group>
            </CommandPrimitive.List>
          </CommandPrimitive>
        </FieldPopoverContent>
      </PopoverPrimitive.Root>
    )
  }

  return (
    <SelectPrimitive.Root
      data-slot="field-select"
      value={selectedValues[0]}
      onValueChange={handleChange}
      disabled={disabled}
      required={required}
    >
      <SelectPrimitive.Trigger
        data-slot="field-select-trigger"
        disabled={disabled}
        className={cn(
          fieldTriggerClassName,
          'group/select w-full justify-between font-normal disabled:pointer-events-none disabled:opacity-50',
          selectedValues.length === 0 && 'text-muted-foreground',
          className,
        )}
      >
        <span className="flex min-w-0 flex-1 items-center gap-2 text-left">
          <SelectPrimitive.Value data-slot="field-select-value" placeholder={selectPlaceholder}>
            {selectedValues.length > 0 ? (
              <span className="line-clamp-1 flex min-w-0 flex-1 items-center gap-2 text-left">
                {selectedOptions[0]?.label}
              </span>
            ) : undefined}
          </SelectPrimitive.Value>
        </span>
        <span className="relative flex size-4 shrink-0 items-center justify-center">
          {showClear && (
            <FieldClearAction
              label="Clear selection"
              onClear={() => handleChange(undefined)}
              className={
                'pointer-events-none absolute inset-0 z-10 opacity-0 group-hover/select:pointer-events-auto group-hover/select:opacity-100 group-focus-within/select:pointer-events-auto group-focus-within/select:opacity-100'
              }
            />
          )}
          <ChevronDown
            className={cn(
              'size-4 opacity-50',
              showClear && 'group-hover/select:opacity-0 group-focus-within/select:opacity-0',
            )}
          />
        </span>
      </SelectPrimitive.Trigger>
      <SelectPrimitive.Portal>
        <SelectPrimitive.Content
          data-slot="field-select-content"
          position="item-aligned"
          className={
            'relative z-50 max-h-(--radix-select-content-available-height) min-w-[8rem] origin-(--radix-select-content-transform-origin) overflow-x-hidden overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-md data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95'
          }
        >
          <SelectPrimitive.ScrollUpButton
            data-slot="field-select-scroll-up-button"
            className="flex cursor-default items-center justify-center py-1"
          >
            <ChevronUp className="size-4" />
          </SelectPrimitive.ScrollUpButton>
          <SelectPrimitive.Viewport className="p-1">
            {options?.map((option) => (
              <SelectPrimitive.Item
                key={option.value}
                value={option.value}
                disabled={option.disabled}
                data-slot="field-select-item"
                className={
                  'relative flex w-full cursor-default items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*=size-])]:size-4 [&_svg:not([class*=text-])]:text-muted-foreground *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-2'
                }
              >
                <span
                  data-slot="field-select-item-indicator"
                  className="absolute right-2 flex size-3.5 items-center justify-center"
                >
                  <SelectPrimitive.ItemIndicator>
                    <Check className="size-4" />
                  </SelectPrimitive.ItemIndicator>
                </span>
                <SelectPrimitive.ItemText>
                  <span className="grid gap-1">
                    <span>{option.label}</span>
                    {option.description != null && (
                      <span className="text-xs leading-snug text-muted-foreground">
                        {option.description}
                      </span>
                    )}
                  </span>
                </SelectPrimitive.ItemText>
              </SelectPrimitive.Item>
            ))}
          </SelectPrimitive.Viewport>
          <SelectPrimitive.ScrollDownButton
            data-slot="field-select-scroll-down-button"
            className="flex cursor-default items-center justify-center py-1"
          >
            <ChevronDown className="size-4" />
          </SelectPrimitive.ScrollDownButton>
        </SelectPrimitive.Content>
      </SelectPrimitive.Portal>
    </SelectPrimitive.Root>
  )
}

export function Cascader({
  value,
  defaultValue,
  onChange,
  options,
  placeholder = 'Select...',
  disabled,
  required,
  className,
}: {
  value?: string[]
  defaultValue?: string[]
  onChange?: (value: string[]) => void
  options?: NestedOption[]
  placeholder?: string
  disabled?: boolean
  required?: boolean
  className?: string
}) {
  const [internalValue, setInternalValue] = useState<string[]>(defaultValue ?? EMPTY_CASCADER_VALUE)
  const selectedPath = value ?? internalValue
  const optionColumns = options ?? EMPTY_CASCADER_OPTIONS
  const [open, setOpen] = useState(false)
  const [columns, setColumns] = useState<NestedOption[][]>([optionColumns])
  const [selected, setSelected] = useState<string[]>(selectedPath)
  const selectedLabels: string[] = []
  let currentOptions = optionColumns
  for (const selectedValue of selectedPath) {
    const selectedOption = currentOptions.find((option) => option.value === selectedValue)
    if (!selectedOption) {
      selectedLabels.length = 0
      break
    }
    currentOptions = selectedOption.children ?? []
    selectedLabels.push(selectedOption.label)
  }

  function handleSelect(option: NestedOption, columnIndex: number) {
    if (option.disabled) return

    const nextSelected = [...selected.slice(0, columnIndex), option.value]
    const childOptions = option.children ?? []
    setSelected(nextSelected)

    setColumns(
      childOptions.length
        ? [...columns.slice(0, columnIndex + 1), childOptions]
        : columns.slice(0, columnIndex + 1),
    )

    if (childOptions.length) return

    onChange?.(nextSelected)
    if (value === undefined) setInternalValue(nextSelected)
    setOpen(false)
  }

  useEffect(() => {
    setColumns([optionColumns])
    setSelected(selectedPath)
  }, [optionColumns, selectedPath])

  return (
    <PopoverPrimitive.Root data-slot="field-popover" open={open} onOpenChange={setOpen}>
      <div className={cn('relative w-full', className)}>
        <PopoverPrimitive.Trigger data-slot="field-popover-trigger" asChild>
          <button
            type="button"
            disabled={disabled}
            aria-expanded={open}
            className={cn(
              fieldTriggerClassName,
              selectedPath.length === 0 && 'text-muted-foreground',
              selectedPath.length > 0 && !disabled && !required && 'pr-8',
            )}
          >
            <span className="flex-1 truncate text-left">
              {selectedLabels.length ? selectedLabels.join(' / ') : placeholder}
            </span>
          </button>
        </PopoverPrimitive.Trigger>
        {selectedPath.length > 0 && !disabled && !required && (
          <FieldClearAction
            label="Clear selection"
            onClear={() => {
              if (value === undefined) setInternalValue(EMPTY_CASCADER_VALUE)
              onChange?.([])
              setOpen(false)
            }}
            className="absolute top-1/2 right-3 z-10 -translate-y-1/2"
          />
        )}
      </div>
      <FieldPopoverContent className="w-auto p-0" align="start">
        <div className="flex divide-x">
          {columns.map((column, columnIndex) => (
            <ul
              // biome-ignore lint/suspicious/noArrayIndexKey: column index represents the cascader depth level.
              key={columnIndex}
              className="max-h-48 min-w-[120px] overflow-y-auto py-1"
            >
              {column.map((option) => (
                <li key={option.value}>
                  <ProButton
                    variant="ghost"
                    size="sm"
                    disabled={option.disabled}
                    onClick={() => handleSelect(option, columnIndex)}
                    className={cn(
                      'h-auto w-full justify-between px-3 py-1.5 disabled:cursor-not-allowed disabled:opacity-50',
                      selected[columnIndex] === option.value && 'bg-accent font-medium',
                    )}
                  >
                    {option.label}
                    {option.children?.length ? (
                      <ChevronRight className="ml-2 size-3 opacity-60" />
                    ) : null}
                  </ProButton>
                </li>
              ))}
            </ul>
          ))}
        </div>
      </FieldPopoverContent>
    </PopoverPrimitive.Root>
  )
}

export function TreeSelect({
  value,
  defaultValue,
  onChange,
  options = [],
  placeholder = 'Select...',
  disabled,
  required,
  multiple = false,
  className,
}: {
  value?: string[]
  defaultValue?: string[]
  onChange?: (value: string[]) => void
  options?: NestedOption[]
  placeholder?: string
  disabled?: boolean
  required?: boolean
  multiple?: boolean
  className?: string
}) {
  const [open, setOpen] = useState(false)
  const [internalValue, setInternalValue] = useState<string[]>(defaultValue ?? [])
  const currentValue = value ?? internalValue
  const selectedValues = new Set(currentValue)
  const selectedLabels: string[] = []
  const optionStack = [...options].reverse()
  while (optionStack.length) {
    const option = optionStack.pop()
    if (!option) continue
    if (selectedValues.has(option.value)) selectedLabels.push(option.label)
    if (option.children) {
      for (let index = option.children.length - 1; index >= 0; index -= 1) {
        optionStack.push(option.children[index])
      }
    }
  }

  function toggle(val: string) {
    if (multiple) {
      if (!selectedValues.has(val)) {
        const nextValue = [...currentValue, val]
        if (value === undefined) setInternalValue(nextValue)
        onChange?.(nextValue)
        return
      }

      const nextValue = currentValue.filter((item) => item !== val)
      if (value === undefined) setInternalValue(nextValue)
      onChange?.(nextValue)
      return
    }

    const nextValue = [val]
    if (value === undefined) setInternalValue(nextValue)
    onChange?.(nextValue)
    setOpen(false)
  }

  return (
    <PopoverPrimitive.Root data-slot="field-popover" open={open} onOpenChange={setOpen}>
      <div className={cn('relative w-full', className)}>
        <PopoverPrimitive.Trigger data-slot="field-popover-trigger" asChild>
          <button
            type="button"
            disabled={disabled}
            aria-expanded={open}
            className={cn(
              fieldTriggerClassName,
              currentValue.length === 0 && 'text-muted-foreground',
              currentValue.length > 0 && !disabled && !required && 'pr-8',
            )}
          >
            <span className="flex-1 truncate text-left">
              {selectedLabels.length ? selectedLabels.join(', ') : placeholder}
            </span>
          </button>
        </PopoverPrimitive.Trigger>
        {currentValue.length > 0 && !disabled && !required && (
          <FieldClearAction
            label="Clear selection"
            onClear={() => {
              if (value === undefined) setInternalValue([])
              onChange?.([])
              setOpen(false)
            }}
            className="absolute top-1/2 right-3 z-10 -translate-y-1/2"
          />
        )}
      </div>
      <FieldPopoverContent className="w-64 p-1" align="start">
        <ul className="max-h-56 overflow-y-auto">
          {options.map((option) => (
            <TreeNode
              key={option.value}
              option={option}
              selected={selectedValues}
              onToggle={toggle}
              multiple={multiple}
            />
          ))}
        </ul>
      </FieldPopoverContent>
    </PopoverPrimitive.Root>
  )
}

function TreeNode({
  option,
  selected,
  onToggle,
  multiple,
}: {
  option: NestedOption
  selected: Set<string>
  onToggle: (value: string) => void
  multiple?: boolean
}) {
  const [expanded, setExpanded] = useState(false)
  const childOptions = option.children ?? []
  const hasChildren = childOptions.length > 0
  const isSelected = selected.has(option.value)
  const expandLabel = expanded ? 'Collapse' : 'Expand'
  const ExpandIcon = expanded ? ChevronDown : ChevronRight

  return (
    <li>
      <div
        className={cn(
          'flex items-center gap-1.5 rounded-sm px-2 py-1 text-sm',
          option.disabled && 'cursor-not-allowed opacity-50',
        )}
      >
        {hasChildren ? (
          <ProButton
            variant="ghost"
            size="icon-xs"
            aria-label={expandLabel}
            className="shrink-0"
            onClick={() => setExpanded(!expanded)}
          >
            <ExpandIcon />
          </ProButton>
        ) : (
          <span className="size-6 shrink-0" aria-hidden />
        )}
        {multiple ? (
          <>
            <CheckboxControl
              checked={isSelected}
              disabled={option.disabled}
              onCheckedChange={() => onToggle(option.value)}
              aria-label={option.label}
            />
            <ProButton
              variant="ghost"
              size="xs"
              disabled={option.disabled}
              onClick={() => onToggle(option.value)}
              className={cn(
                'h-auto flex-1 cursor-pointer justify-start rounded-sm px-1 py-0 text-left disabled:cursor-not-allowed',
                isSelected && 'font-medium',
              )}
            >
              {option.label}
            </ProButton>
          </>
        ) : (
          <ProButton
            variant="ghost"
            size="xs"
            disabled={option.disabled}
            onClick={() => onToggle(option.value)}
            className={cn(
              'h-auto flex-1 cursor-pointer justify-between rounded-sm px-1 py-0.5 text-left disabled:cursor-not-allowed',
              isSelected && 'font-medium',
            )}
          >
            <span>{option.label}</span>
            {isSelected && <Check className="size-3.5 text-primary" />}
          </ProButton>
        )}
      </div>
      {expanded && hasChildren && (
        <ul className="pl-4">
          {childOptions.map((child) => (
            <TreeNode
              key={child.value}
              option={child}
              selected={selected}
              onToggle={onToggle}
              multiple={multiple}
            />
          ))}
        </ul>
      )}
    </li>
  )
}

function getSelectedValues(value: string | string[] | undefined) {
  if (Array.isArray(value)) return value
  if (typeof value === 'string') return [value]
  return []
}

function renderSelectedOptions(
  selectedOptions: NestedOption[],
  selectedCount: number,
  placeholder: ReactNode,
) {
  if (selectedCount === 1) {
    return <span className="truncate">{selectedOptions[0]?.label}</span>
  }

  if (selectedCount <= 1) return placeholder

  return (
    <>
      {selectedOptions.slice(0, 2).map((option) => (
        <span
          key={option.value}
          className={
            'inline-flex max-w-24 shrink-0 items-center justify-center truncate rounded-full bg-secondary px-1.5 py-0.5 text-xs font-medium text-secondary-foreground'
          }
        >
          {option.label}
        </span>
      ))}
      {selectedCount > 2 && (
        <span
          className={
            'inline-flex shrink-0 items-center justify-center rounded-full bg-secondary px-1.5 py-0.5 text-xs font-medium text-secondary-foreground'
          }
        >
          +{selectedCount - 2}
        </span>
      )}
    </>
  )
}

'use client'

import { CheckIcon } from 'lucide-react'
import { Checkbox as CheckboxPrimitive, Switch as SwitchPrimitive } from 'radix-ui'
import { type ComponentProps, type ReactNode, useId, useState } from 'react'
import { cn } from '@/lib/utils'

export function Checkbox({
  value,
  defaultValue,
  onChange,
  options,
  disabled,
  children,
  id,
  ...props
}: Omit<
  ComponentProps<typeof CheckboxPrimitive.Root>,
  'value' | 'defaultValue' | 'onChange' | 'checked' | 'defaultChecked' | 'onCheckedChange'
> & {
  value?: boolean | string[]
  defaultValue?: boolean | string[]
  onChange?: (checked: boolean | string[]) => void
  options?: {
    label: ReactNode
    value: string
    description?: ReactNode
    disabled?: boolean
  }[]
  children?: ReactNode
}) {
  const generatedId = useId()
  const checkboxId = id ?? generatedId
  const [internalValues, setInternalValues] = useState<string[]>(
    Array.isArray(defaultValue) ? defaultValue : [],
  )
  const values = Array.isArray(value) ? value : internalValues

  function commit(next: string[]) {
    if (value === undefined) setInternalValues(next)
    onChange?.(next)
  }

  if (options?.length) {
    const valueSet = new Set(values)

    return (
      <div className="flex flex-col gap-2">
        {options.map((option, index) => {
          const itemId = `${checkboxId}-${index}`

          return (
            <div key={option.value} className="flex items-start gap-2">
              <CheckboxControl
                id={itemId}
                checked={valueSet.has(option.value)}
                disabled={disabled || option.disabled}
                onCheckedChange={(nextChecked) => {
                  if (nextChecked === true) {
                    if (!valueSet.has(option.value)) commit([...values, option.value])
                    return
                  }

                  commit(values.filter((item) => item !== option.value))
                }}
                {...props}
              />
              <label
                htmlFor={itemId}
                className={cn(
                  'grid gap-1 text-sm leading-none font-normal select-none',
                  disabled || option.disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
                )}
              >
                <span>{option.label}</span>
                {option.description != null && (
                  <span className="text-xs leading-snug text-muted-foreground">
                    {option.description}
                  </span>
                )}
              </label>
            </div>
          )
        })}
      </div>
    )
  }

  return (
    <div className="flex items-start gap-2">
      <CheckboxControl
        id={checkboxId}
        checked={typeof value === 'boolean' ? value : undefined}
        defaultChecked={typeof defaultValue === 'boolean' ? defaultValue : undefined}
        onCheckedChange={(checked) => onChange?.(checked === true)}
        disabled={disabled}
        {...props}
      />
      {children != null && (
        <label
          htmlFor={checkboxId}
          className={cn(
            'flex items-center gap-2 text-sm leading-none font-normal select-none',
            disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
          )}
        >
          {children}
        </label>
      )}
    </div>
  )
}

export function CheckboxControl({
  className,
  ...props
}: Omit<
  ComponentProps<typeof CheckboxPrimitive.Root>,
  'checked' | 'defaultChecked' | 'onChange' | 'onCheckedChange' | 'value'
> & {
  checked?: boolean | 'indeterminate'
  defaultChecked?: boolean | 'indeterminate'
  onCheckedChange?: (checked: boolean | 'indeterminate') => void
}) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        'peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs transition-shadow outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:data-[state=checked]:bg-primary',
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none"
