function getDateRangeLabel(from: Date | undefined, to: Date | undefined, placeholder: string) {
  if (from && to) return `${format(from, 'LLL dd, y')} - ${format(to, 'LLL dd, y')}`
  if (from) return format(from, 'LLL dd, y')
  return placeholder
}

