'use client'

import { cva } from 'class-variance-authority'
import { File, Upload as UploadIcon, X } from 'lucide-react'
import { createContext, type ReactNode, type RefObject, useContext, useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../../button'

export interface UploadFile {
  uid: string
  name: string
  url?: string
  status?: 'uploading' | 'done' | 'error'
  size?: number
}

type UploadResult = string | Partial<UploadFile> | null | false | undefined

const UploadContext = createContext<{
  inputRef: RefObject<HTMLInputElement | null>
  files: UploadFile[]
  reachedMax: boolean
  disabled: boolean
  addFiles: (selectedFileList: FileList | File[] | null) => Promise<void>
  removeFile: (uid: string) => void
} | null>(null)
const uploadTriggerVariants = cva('w-full', {
  variants: {
    variant: {
      compact:
        'justify-start bg-transparent px-3 font-normal dark:bg-input/30 dark:hover:bg-input/50',
      dropzone: 'h-auto flex-col gap-2 border-2 border-dashed p-6 text-muted-foreground',
    },
    dragging: {
      true: 'border-primary bg-primary/5',
    },
  },
  defaultVariants: {
    variant: 'dropzone',
    dragging: false,
  },
})

function useUploadContext() {
  const context = useContext(UploadContext)
  if (!context) throw new Error('Upload components must be used inside <Upload>.')
  return context
}

export function Upload({
  value,
  onChange,
  upload,
  accept,
  multiple = true,
  maxCount,
  disabled,
  className,
  children,
}: {
  value?: UploadFile[]
  onChange?: (files: UploadFile[]) => void
  upload?: (
    files: File[],
    context: { maxCount?: number; multiple: boolean },
  ) => UploadResult | UploadResult[] | Promise<UploadResult | UploadResult[]>
  accept?: string
  multiple?: boolean
  maxCount?: number
  disabled?: boolean
  className?: string
  children?: ReactNode
}) {
  const inputRef = useRef<HTMLInputElement>(null)
  const [internalValue, setInternalValue] = useState<UploadFile[]>([])
  const files = value ?? internalValue
  const remainingSlots =
    multiple && maxCount !== undefined ? Math.max(maxCount - files.length, 0) : 1
  const reachedMax = remainingSlots === 0

  function setFiles(nextFiles: UploadFile[]) {
    if (value === undefined) setInternalValue(nextFiles)
    onChange?.(nextFiles)
  }

  async function addFiles(selectedFileList: FileList | File[] | null) {
    if (!selectedFileList) return

    const selectedFiles = Array.from(selectedFileList).slice(0, remainingSlots)
    if (!selectedFiles.length) return

    let uploadResults: UploadResult[] | undefined
    if (upload) {
      try {
        const result = await Promise.resolve(upload(selectedFiles, { maxCount, multiple }))
        if (Array.isArray(result)) uploadResults = result
        else uploadResults = [result]
      } catch {
        uploadResults = Array.from({ length: selectedFiles.length }, () => ({ status: 'error' }))
      }
    }

    const newFiles = selectedFiles.flatMap((file, index) => {
      const result = uploadResults?.[index]
      if (result === false || result === null) return []

      const baseFile: UploadFile = {
        uid: `${Date.now()}-${Math.random()}`,
        name: file.name,
        size: file.size,
        status: 'done',
      }

      if (typeof result === 'string') {
        return [{ ...baseFile, url: result }]
      }
      if (typeof result === 'object') {
        return [{ ...baseFile, ...result }]
      }
      return [{ ...baseFile, url: URL.createObjectURL(file) }]
    })
    if (!newFiles.length) return

    if (!multiple) {
      for (const file of files) {
        if (file.url?.startsWith('blob:')) URL.revokeObjectURL(file.url)
      }
      setFiles([newFiles[0]])
      return
    }

    setFiles([...files, ...newFiles])
  }

  function removeFile(uid: string) {
    const removedFile = files.find((file) => file.uid === uid)
    if (removedFile?.url?.startsWith('blob:')) URL.revokeObjectURL(removedFile.url)
    setFiles(files.filter((file) => file.uid !== uid))
  }

  return (
    <UploadContext.Provider
      value={{
        inputRef,
        files,
        reachedMax,
        disabled: !!disabled,
        addFiles,
        removeFile,
      }}
    >
      <div className={cn('space-y-2', className)}>
        <input
          ref={inputRef}
          type="file"
          className="hidden"
          accept={accept}
          multiple={multiple}
          disabled={disabled || reachedMax}
          onChange={async (e) => {
            await addFiles(e.target.files)
            e.currentTarget.value = ''
          }}
        />
        {children}
      </div>
    </UploadContext.Provider>
  )
}

export function UploadTrigger({
  variant = 'dropzone',
  className,
}: {
  variant?: 'compact' | 'dropzone'
  className?: string
}) {
  const upload = useUploadContext()
  const [dragging, setDragging] = useState(false)
  const fileNames = upload.files.map((file) => file.name).join(', ')
  const hasFiles = upload.files.length > 0
  const canUpload = !upload.disabled && !upload.reachedMax
  const triggerClassName =
    variant === 'dropzone' && canUpload
      ? cn('cursor-pointer hover:border-primary hover:bg-primary/5', className)
      : className
  const triggerContent = renderUploadTriggerContent({ variant, hasFiles, fileNames })

  if (variant === 'dropzone' && upload.reachedMax) return null

  return (
    <ProButton
      variant="outline"
      aria-label="Upload files"
      disabled={!canUpload}
      className={uploadTriggerVariants({
        variant,
        dragging,
        className: triggerClassName,
      })}
      onClick={() => upload.inputRef.current?.click()}
      onDragOver={(event) => {
        event.preventDefault()
        if (canUpload) setDragging(true)
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={(event) => {
        event.preventDefault()
        setDragging(false)
        if (canUpload) upload.addFiles(event.dataTransfer.files).catch(() => {})
      }}
    >
      {triggerContent}
    </ProButton>
  )
}

function renderUploadTriggerContent({
  variant,
  hasFiles,
  fileNames,
}: {
  variant: 'compact' | 'dropzone'
  hasFiles: boolean
  fileNames: string
}) {
  const label = hasFiles ? fileNames : 'Upload files'
  if (variant === 'compact') {
    return (
      <>
        <span
          className={cn('min-w-0 flex-1 truncate text-left', !hasFiles && 'text-muted-foreground')}
        >
          {label}
        </span>
        <UploadIcon className="ml-2 size-4 shrink-0 text-muted-foreground" />
      </>
    )
  }

  return (
    <>
      <UploadIcon className="size-6" />
      <span>{hasFiles ? fileNames : 'Click or drag to upload'}</span>
    </>
  )
}

export function UploadFileList({ className }: { className?: string }) {
  const upload = useUploadContext()

  if (!upload.files.length) return null

  return (
    <ul className={cn('space-y-1', className)}>
      {upload.files.map((file) => (
        <li
          key={file.uid}
          className="flex items-center gap-2 rounded-md border px-3 py-1.5 text-sm"
        >
          <File className="size-4 shrink-0 text-muted-foreground" />
          <span className="flex-1 truncate">{file.name}</span>
          {!upload.disabled && (
            <ProButton
              variant="ghost"
              size="icon-xs"
              aria-label={`Remove ${file.name}`}
              onClick={() => upload.removeFile(file.uid)}
              className="shrink-0"
            >
              <X />
            </ProButton>
          )}
        </li>
      ))}
    </ul>
  )
}

'use client'

import {
  closestCenter,
  DndContext,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core'
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { ArrowDown, ArrowUp, Copy, GripVertical, Plus, Trash2 } from 'lucide-react'
import { type CSSProperties, type ReactNode, useEffect, useState } from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../../button'

function createArrayFieldId() {
  return `item-${Math.random().toString(36).slice(2)}`
}

type ArrayFieldSortMode = 'button' | 'drag' | 'none'

interface ArrayFieldRenderHelpers<TItem extends object> {
  update: (next: TItem | ((current: TItem) => TItem)) => void
  duplicate: () => void
  remove: () => void
  moveUp: () => void
  moveDown: () => void
}

interface ArrayFieldProps<TItem extends object> {
  value?: TItem[]
  onChange?: (value: TItem[]) => void
  defaultValue?: TItem[]
  newItem: () => TItem
  renderItem: (item: TItem, index: number, helpers: ArrayFieldRenderHelpers<TItem>) => ReactNode
  max?: number
  min?: number
  sortable?: Exclude<ArrayFieldSortMode, 'none'> | false
  variant?: 'outline' | 'ghost'
  disabled?: boolean
  className?: string
}

export function ArrayField<TItem extends object = Record<string, unknown>>({
  value,
  onChange,
  defaultValue,
  newItem,
  renderItem,
  max,
  min = 0,
  sortable = 'drag',
  variant = 'outline',
  disabled,
  className,
}: ArrayFieldProps<TItem>) {
  const [internalValue, setInternalValue] = useState<TItem[]>(defaultValue ?? [])
  const items = value ?? internalValue
  const [ids, setIds] = useState<string[]>(() =>
    Array.from({ length: items.length }, createArrayFieldId),
  )
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )
  const canAddItem = max === undefined || items.length < max
  const sortMode: ArrayFieldSortMode = sortable === false ? 'none' : sortable

  useEffect(() => {
    setIds((prev) => {
      if (prev.length === items.length) return prev
      if (items.length > prev.length) {
        return [...prev, ...Array.from({ length: items.length - prev.length }, createArrayFieldId)]
      }
      return prev.slice(0, items.length)
    })
  }, [items.length])

  function commit(next: TItem[]) {
    if (value === undefined) setInternalValue(next)
    onChange?.(next)
  }

  function remove(index: number) {
    setIds((prev) => [...prev.slice(0, index), ...prev.slice(index + 1)])
    commit([...items.slice(0, index), ...items.slice(index + 1)])
  }

  function update(index: number, next: TItem | ((current: TItem) => TItem)) {
    commit(
      items.map((item, itemIndex) => {
        if (itemIndex !== index) return item
        if (typeof next === 'function') return next(item)
        return next
      }),
    )
  }

  function duplicate(index: number) {
    setIds((prev) => [...prev.slice(0, index + 1), createArrayFieldId(), ...prev.slice(index + 1)])
    commit([...items.slice(0, index + 1), structuredClone(items[index]), ...items.slice(index + 1)])
  }

  function move(index: number, nextIndex: number) {
    if (nextIndex < 0 || nextIndex >= items.length || index === nextIndex) return
    setIds((prev) => arrayMove(prev, index, nextIndex))
    commit(arrayMove(items, index, nextIndex))
  }

  const itemNodes = items.map((item, index) => {
    const itemContent = renderItem(item, index, {
      update: (next) => update(index, next),
      duplicate: () => duplicate(index),
      remove: () => remove(index),
      moveUp: () => move(index, index - 1),
      moveDown: () => move(index, index + 1),
    })

    const itemProps: ArrayFieldItemProps = {
      onDuplicate: () => duplicate(index),
      onRemove: () => remove(index),
      onMoveUp: () => move(index, index - 1),
      onMoveDown: () => move(index, index + 1),
      disabled,
      sortMode,
      variant,
      canDuplicate: canAddItem,
      canRemove: items.length > min,
      canMoveUp: index > 0,
      canMoveDown: index < items.length - 1,
      children: itemContent,
    }

    return sortMode === 'drag' ? (
      <SortableArrayFieldItem key={ids[index]} id={ids[index]} {...itemProps} />
    ) : (
      <ArrayFieldItem key={ids[index]} {...itemProps} />
    )
  })

  return (
    <div className={cn('space-y-2', className)}>
      {sortMode === 'drag' ? (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={({ active, over }) => {
            if (!over || active.id === over.id) return

            const oldIndex = ids.indexOf(String(active.id))
            const newIndex = ids.indexOf(String(over.id))
            if (oldIndex === -1 || newIndex === -1) return

            move(oldIndex, newIndex)
          }}
        >
          <SortableContext items={ids} strategy={verticalListSortingStrategy}>
            {itemNodes}
          </SortableContext>
        </DndContext>
      ) : (
        itemNodes
      )}

      {canAddItem && (
        <ProButton
          variant="outline"
          disabled={disabled}
          onClick={() => {
            setIds((prev) => [...prev, createArrayFieldId()])
            commit([...items, newItem()])
          }}
          className="w-full border-dashed"
        >
          <Plus />
          Add item
        </ProButton>
      )}
    </div>
  )
}

function SortableArrayFieldItem({
  id,
  ...props
}: ArrayFieldItemProps & {
  id: string
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id,
  })
  const style: CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  }

  return (
    <ArrayFieldItem
      ref={setNodeRef}
      style={style}
      dragHandleProps={{ ...attributes, ...listeners }}
      {...props}
    />
  )
}

interface ArrayFieldItemProps {
  children: ReactNode
  onDuplicate: () => void
  onRemove: () => void
  onMoveUp: () => void
  onMoveDown: () => void
  disabled?: boolean
  sortMode: ArrayFieldSortMode
  variant: 'outline' | 'ghost'
  canDuplicate?: boolean
  canRemove?: boolean
  canMoveUp?: boolean
  canMoveDown?: boolean
  ref?: (node: HTMLDivElement | null) => void
  style?: CSSProperties
  dragHandleProps?: Record<string, unknown>
}

function ArrayFieldItem({
  ref,
  style,
  children,
  onDuplicate,
  onRemove,
  onMoveUp,
  onMoveDown,
  disabled,
  sortMode,
  variant,
  canDuplicate = true,
  canRemove = true,
  canMoveUp = true,
  canMoveDown = true,
  dragHandleProps,
}: ArrayFieldItemProps) {
  return (
    <div
      ref={ref}
      style={style}
      className={cn(
        'group relative flex items-start gap-2',
        variant === 'outline' && 'rounded-md border bg-card p-3',
      )}
    >
      <div className="min-w-0 flex-1 space-y-3">{children}</div>

      {(canDuplicate || canRemove || sortMode !== 'none') && (
        <div className="mt-0.5 flex shrink-0 items-center gap-1">
          {canDuplicate && (
            <ProButton
              variant="ghost"
              size="icon-sm"
              disabled={disabled}
              onClick={onDuplicate}
              aria-label="Duplicate item"
            >
              <Copy />
            </ProButton>
          )}

          {canRemove && (
            <ProButton
              variant="ghost"
              size="icon-sm"
              disabled={disabled}
              onClick={onRemove}
              aria-label="Remove item"
            >
              <Trash2 className="text-destructive" />
            </ProButton>
          )}

          {sortMode === 'drag' && (
            <ProButton
              {...dragHandleProps}
              variant="ghost"
              size="icon-sm"
              disabled={disabled}
              className="cursor-grab active:cursor-grabbing disabled:cursor-not-allowed"
              aria-label="Drag to reorder"
            >
              <GripVertical />
            </ProButton>
          )}

          {sortMode === 'button' && (
            <>
              <ProButton
                variant="ghost"
                size="icon-sm"
                disabled={disabled || !canMoveUp}
                onClick={onMoveUp}
                aria-label="Move item up"
              >
                <ArrowUp />
              </ProButton>

              <ProButton
                variant="ghost"
                size="icon-sm"
                disabled={disabled || !canMoveDown}
                onClick={onMoveDown}
                aria-label="Move item down"
              >
                <ArrowDown />
              </ProButton>
            </>
          )}
        </div>
      )}
    </div>
  )
}
